/// <summary>
/// Extension class for HMIMItemMaterialSimpleV2Entity
/// </summary>
[ExtensionOf(tableStr(HMIMItemMaterialSimpleV2Entity))]
final class METHMIMItemMaterialSimpleV2Entity_Extension
{
}

Method.Source:
/// <summary>
/// Validates the records before they are written to the database.
/// </summary>
/// <returns>true if the record is valid; otherwise false</returns>
public boolean validateWrite()
{
    boolean ret;

    if (this.ItemId && this.RegCode)
    {
        this.ClassCode = HMIMDivision::find(this.DivisionCode).ClassCode;
    }

    ret = next validateWrite();

    return ret;
}

/// <summary>
/// CoC method for InsertEntityDataSource method
/// </summary>
/// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
/// <returns>true of false</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean             ret;
    HMIMDivision        division;
    HMIMItemMaterial    itemMaterial;

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(HMIMItemMaterialSimpleV2Entity, METHMIMItemMaterial))
    {
        // We will handle persistence for the METH datasource ourselves to avoid duplicate framework inserts.
        // Tell the framework not to perform DB operation for this datasource.
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
    }
    else if (_dataSourceCtx.name() == dataEntityDataSourceStr(HMIMItemMaterialSimpleV2Entity, HMIMItemMaterial))
    {
        itemMaterial = HMIMItemMaterial::findByItemRegCode(this.ItemId, this.RegCode);
        // We will handle persistence for the METH datasource ourselves to avoid duplicate framework inserts.
        // Tell the framework not to perform DB operation for this datasource.
        if (itemMaterial.RecId && itemMaterial.DivisionCode != this.DivisionCode)
        {
            // If record already exists, prevent insert operation.
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
        }
    }
    ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(HMIMItemMaterialSimpleV2Entity, HMIMItemMaterial))
    {
        if (this.ItemId && this.RegCode)
        {
            ttsbegin;
            this.metSaveOtherTables(_dataSourceCtx);
            ttscommit;
        }
    }

    return ret;
}

/// <summary>
/// Updating the class code based on the division code.
/// </summary>
/// <param name = "_entityCtx">Entity.</param>
/// <param name = "_dataSourceCtx">Entity datasource.</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(HMIMItemMaterialSimpleV2Entity, HMIMItemMaterial))
    {
        HMIMDivision division = HMIMDivision::find(this.DivisionCode);

        this.ClassCode = division.ClassCode;
    }
}

/// <summary>
/// Finds record buffer for data source and return
/// </summary>
/// <param name = "_entityCtx">Entity context</param>
/// <param name = "_dataSourceCtx">Data source runtime context</param>
/// <returns>Record buffer associated with data source</returns>
public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    Common ret = next findEntityDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(HMIMItemMaterialSimpleV2Entity, METHMIMItemMaterial))
    {
        ret = METHMIMItemMaterial::find(this.RecId);
    }

    return ret;
}

/// <summary>
/// Updating the child datasources on updation of HMIMItemMaterial.
/// </summary>
/// <param name = "_entityCtx">Entity.</param>
/// <param name = "_dataSourceCtx">Entity datasource.</param>
/// <returns>Returns true if record updates, Otherwise false.</returns>
public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    ret = next updateEntityDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(HMIMItemMaterialSimpleV2Entity, HMIMItemMaterial))
    {
        ttsbegin;
        this.metSaveOtherTables(_dataSourceCtx);
        ttscommit;
    }

    return ret;
}

/// <summary>
/// Updating the METHMIMItemMaterial table records on updating of entity changes.
/// </summary>
/// <param name = "_dataSourceCtx">Entity datasource.</param>
private void metSaveOtherTables(DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    switch(_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(HMIMItemMaterialSimpleV2Entity, HMIMItemMaterial):
            if (this.RecordId)
            {
                METHMIMItemMaterial metHmimItemMaterial = METHMIMItemMaterial::find(this.RecordId, true);

                if (metHmimItemMaterial.RecId)
                {
                    metHmimItemMaterial.EMSCodeSpillageSchedId  = this.METEMSCodeSpillageSchedId;
                    metHmimItemMaterial.SubsideryHazard         = this.METSubsideryHazard;
                    metHmimItemMaterial.PoisonousByInhalation   = this.METPoisonousByInhalation;

                    if (metHmimItemMaterial.validateWrite())
                    {
                        metHmimItemMaterial.update();
                    }
                    else
                    {
                        throw error(strFmt('@MET:ValidateSubsidiaryHazard', tableStr(METHMIMItemMaterial)));
                    }
                }
                else
                {
                    metHmimItemMaterial.EMSCodeSpillageSchedId  = this.METEMSCodeSpillageSchedId;
                    metHmimItemMaterial.SubsideryHazard         = this.METSubsideryHazard;
                    metHmimItemMaterial.PoisonousByInhalation   = this.METPoisonousByInhalation;
                    metHmimItemMaterial.RefRecId                = this.RecordId;

                    if (metHmimItemMaterial.validateWrite())
                    {
                        metHmimItemMaterial.insert();
                    }
                    else
                    {
                        throw error(strFmt('@MET:ValidateSubsidiaryHazard', tableStr(METHMIMItemMaterial)));
                    }
                }
            }
            break;
    }

    _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
    _dataSourceCtx.setDataSaved(true);
}
